from fractions import Fraction
import random
def rdiv(z,s):
    if s==0: return z
    d=2**s
    if z>=0: return (2*z+d)//(2*d)
    return -((2*(-z)+d)//(2*d))
def ref(z,s):
    q = Fraction(z, 2**s)
    # round to nearest, ties away from zero
    fl = q.numerator // q.denominator
    frac = q - fl
    if frac > Fraction(1,2): r = fl+1
    elif frac < Fraction(1,2): r = fl
    else: r = fl+1 if q > 0 else fl  # tie away from zero
    if q < 0 and frac == Fraction(1,2): r = fl-1 if fl >= 0 else fl  # careful
    return r
# simpler exact reference
def ref2(z,s):
    from fractions import Fraction
    q = Fraction(z, 2**s)
    # away from zero rounding: sign(q)*floor(|q|+1/2)
    if q >= 0:
        return (q + Fraction(1,2)).__floor__()
    else:
        return -((-q + Fraction(1,2)).__floor__()
r=random.Random(7)
bad=0
for _ in range(200000):
    z=r.randint(-10**7,10**7); s=r.randint(0,16)
    a=rdiv(z,s); b=ref2(z,s)
    if a!=b:
        bad+=1
        if bad<10: print("DIFF",z,s,a,b)
print("rounding mismatches:",bad)
'
